#include <iostream>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    int total = n * 5;
    if (n >= 10) {
        // 乘以 0.9 转为 double 后赋给 int 会自动截断小数向下取整
        total = int(total * 0.9);
    }
    cout << total << endl;
    return 0;
}

