#include <iostream>
using namespace std;

int main() {
    int L, R;
    if (!(cin >> L >> R)) return 0;
    int oddSum = 0;
    int evenSum = 0;
    for (int i = L; i <= R; i++) {
        if (i % 2 == 1) {
            oddSum += i;
        } else {
            evenSum += i;
        }
    }
    cout << oddSum << " " << evenSum << endl;
    return 0;
}
